import { PreferenceContribution } from '@capital/core/preferences';
import { ContainerModule } from "@capital/shared/inversify";
import { regContainerModule } from '@capital/core/plugin';
import { EmbeddedAgentWidget } from './embedded-agent-widget';
import { CommandContribution } from '@capital/core/commands';
import { FrontendApplicationContribution } from "@capital/core";
import { EmbeddedAgentPreferencesSchema } from './common/ai-embedded-agent-preference';
import { AICodeCompletionPreferencesSchema } from './common/ai-code-completion-preference';
import { AIFrontendApplicationContribution } from './ai-code-frontend-application-contribution';

const AIAgentModule = new ContainerModule(
  (bind: any) => {
  bind(EmbeddedAgentWidget).toSelf().inSingletonScope();
  bind(AIFrontendApplicationContribution).toSelf().inSingletonScope();
  bind(FrontendApplicationContribution).to(AIFrontendApplicationContribution);

  bind(CommandContribution).toService(EmbeddedAgentWidget);
  bind(PreferenceContribution).toConstantValue({ schema: EmbeddedAgentPreferencesSchema });
  bind(PreferenceContribution).toConstantValue({ schema: AICodeCompletionPreferencesSchema });
})

// 注册容器模块到插件中心 
regContainerModule(AIAgentModule);