import * as monaco from "@capital/shared/monaco-editor";

// 将 PascalCase 转换为 camelCase
function toCamelCase(str) {
  if (!str) {
    return ''
  }
  return str.charAt(0).toLowerCase() + str.slice(1)
}

// 提取上下文信息
function extractContextInfo(fullText, position) {
  const lines = fullText.split('\n')
  const currentLine = lines[position.lineNumber - 1]
  const previousLines = lines.slice(0, position.lineNumber - 1)
  const nextLines = lines.slice(position.lineNumber)

  // 提取变量和函数名
  const variables = []
  const functions = []
  const regex = /(let|const|var)\s+(\w+)|function\s+(\w+)/g
  let match
  while ((match = regex.exec(fullText)) !== null) {
    if (match[2]) variables.push(match[2]) // 变量
    if (match[3]) functions.push(match[3]) // 函数
  }

  return {
    currentLine,
    previousLines,
    nextLines,
    variables,
    functions,
    fullText
  }
}

/**
 * 提取导入的类或模块
 */
function extractImportedItems(fullText, isCurrentLine) {
  // 定义基础正则表达式部分
  const baseRegex = /import\s+([\w.]+|["']([^"']+)["'])/
  // 根据 isCurrentLine 参数决定是否包含 as 部分
  const importRegex = isCurrentLine
    ? new RegExp(baseRegex.source, 'g')
    : new RegExp(baseRegex.source + '\\s+as\\s+(\\w+)', 'g')

  const importedItems = []
  let match

  while ((match = importRegex.exec(fullText)) !== null) {
    const fullPath = match[1].replace(/["']/g, '') // 去掉引号
    const lastPart = fullPath.split('.').pop().split('/').pop() // 获取最后一个部分

    let itemName = lastPart
    if (isCurrentLine && match[3]) {
      itemName = match[3] // 使用别名
    }

    importedItems.push(itemName)
  }

  return importedItems
}

// 生成导如模块建议
function generateImportSuggestions(importedItems, textUntilPosition, position) {
  const suggestions = []
  // 遍历导入的类或模块，生成建议
  importedItems.forEach(item => {
    if (item.toLowerCase().startsWith(textUntilPosition.toLowerCase())) {
      suggestions.push({
        insertText: item,
        range: new monaco.Range(position.lineNumber, 1, position.lineNumber, position.column)
      })
    }
  })

  return suggestions
}

// 根据上下文生成建议
function generateSuggestions(contextInfo, textUntilPosition, position) {
  const { currentLine, variables, functions } = contextInfo
  if (!currentLine || currentLine === '') return []
  const suggestions = []

  // 如果当前行以 "import" 开头，建议 import 的 as 别名
  if (currentLine.startsWith('import') && currentLine.includes('as')) {
    // 提取当前行的类或模块
    const item = extractImportedItems(currentLine, true)
    const alias = item[0]//toCamelCase(item[0])
    if (alias) {
      suggestions.push({
        insertText: alias,
        label: alias,
        kind: monaco.languages.CompletionItemKind.Variable,
        sortText: '0'
      })
    }
  }

  // 如果当前行以 "log" 开头，建议 log.info
  if (currentLine.trim().startsWith('log')) {
    suggestions.push({
      insertText: 'log.info("打印日志输出...");',
      range: new monaco.Range(position.lineNumber, 1, position.lineNumber, position.column)
    })
  }

  // 如果当前行以 "var xx = ()" 开头，建议函数模板
  if (
    (currentLine.startsWith('var') || currentLine.startsWith('const') || currentLine.startsWith('let')) &&
    currentLine.includes('= () ') && !currentLine.includes('=>')
  ) {
    // const varName = currentLine.split(' ')[1] // 提取变量名
    // 生成箭头函数模板
    const insertText = '=> {\n\t\n}';
    suggestions.push({
      insertText: insertText,
      range: new monaco.Range(
        position.lineNumber, // 当前行
        position.column, // 从行首开始
        position.lineNumber, // 当前行
        position.column // 到当前光标位置
      )
    })
  }

  // 如果当前行以 "if" 开头，建议 if 语句模板
  if (currentLine.trim().startsWith('if')) {
    suggestions.push({
      insertText: 'if (condition) {\n\t\n}',
      range: new monaco.Range(position.lineNumber, 1, position.lineNumber, position.column)
    })
  }

  // 如果当前行以 "for" 开头，建议 for 循环模板
  if (currentLine.trim().startsWith('for')) {
    suggestions.push({
      insertText: 'for (item in collection) {\n\t\n}',
      range: new monaco.Range(position.lineNumber, 1, position.lineNumber, position.column)
    })
  }

  // 如果当前行以 "try" 开头，建议 try 循环模板
  if (currentLine.trim().startsWith('try')) {
    suggestions.push({
      insertText: 'try {\r\n\t\r\n} catch (e) {\r\n\t\r\n}',
      range: new monaco.Range(position.lineNumber, 1, position.lineNumber, position.column)
    })
  }

  // 如果当前行以 "each" 结尾，建议 each 循环模板
  if (currentLine.trim().endsWith('each')) {
    suggestions.push({
      insertText: `(item => {\n\t\n})`,
      range: new monaco.Range(position.lineNumber, position.column, position.lineNumber, position.column)
    })
  }

  // 如果当前输入匹配变量名，建议变量
  // variables.forEach(variable => {
  //   if (variable.toLowerCase().startsWith(textUntilPosition.toLowerCase())) {
  //     suggestions.push({
  //       insertText: variable,
  //       range: new monaco.Range(position.lineNumber, 1, position.lineNumber, position.column)
  //     })
  //   }
  // })

  // 如果当前输入匹配函数名，建议函数
  functions.forEach(func => {
    if (func.toLowerCase().startsWith(textUntilPosition.toLowerCase())) {
      suggestions.push({
        insertText: func,
        range: new monaco.Range(position.lineNumber, 1, position.lineNumber, position.column)
      })
    }
  })

  // 如果当前输入匹配关键字，建议关键字
  if (currentLine && currentLine.length > 1) {
    const keywords = ['const', 'var', 'let', 'if', 'else', 'for', 'db', 'return']
    keywords.forEach(keyword => {
      if (keyword.toLowerCase().startsWith(textUntilPosition.toLowerCase())) {
        suggestions.push({
          insertText: keyword,
          range: new monaco.Range(position.lineNumber, 1, position.lineNumber, position.column)
        })
      }
    })
  }

  // 提取导入的类或模块
  const importedItems = extractImportedItems(contextInfo.fullText)
  // 生成导入的类或模块的建议
  const importSuggestions = generateImportSuggestions(importedItems, textUntilPosition, position)
  if (importSuggestions.length > 0) {
    suggestions.push(...importSuggestions)
  }
  return suggestions
}

/**
 * 内联建议提供者
 */
const InlineCompletionItemProvider = {
  provideInlineCompletions: (model, position, context, token) => {
    // 获取当前行的文本
    const textUntilPosition = model.getValueInRange({
      startLineNumber: position.lineNumber,
      startColumn: 1,
      endLineNumber: position.lineNumber,
      endColumn: position.column
    })

    // 获取当前文件的全部内容
    const fullText = model.getValue()

    // 提取上下文信息
    const contextInfo = extractContextInfo(fullText, position)

    // 基于上下文生成建议
    const suggestions = generateSuggestions(contextInfo, textUntilPosition, position)
    // 返回过滤后的建议
    return { 
      items: suggestions,
      enableForwardStability: true 
    }
  },
  disposeInlineCompletions: () => {
    // 释放资源
    return undefined
  }
}
export default InlineCompletionItemProvider
